import { approvalCardActivity, resolvedApprovalCardActivity } from "./cards.js";
import { splitTextByJsonBytes } from "./text.js";
/** Teams refuses a message activity much above 28 KB, so each part keeps its JSON-encoded text well under it. */
const MESSAGE_TEXT_MAX_BYTES = 20_000;
const DEFAULT_UPDATE_INTERVAL_MS = 1_500;
const FAILURE_TEXT = "The agent hit an error while handling this message.";
export function emptyTeamsChannelState() {
    return { address: null, live: null, approvalCards: {} };
}
export function teamsToolLabel(labels, toolName) {
    if (labels === undefined) {
        return toolName;
    }
    return (typeof labels === "function" ? labels(toolName) : labels[toolName]) ?? toolName;
}
function markdown(text) {
    return { type: "message", text, textFormat: "markdown" };
}
export function buildDefaultTeamsEvents(deps) {
    const now = deps.now ?? Date.now;
    const stream = deps.reply.mode === "stream";
    const interval = (deps.reply.mode === "stream" ? deps.reply.updateIntervalMs : undefined) ??
        DEFAULT_UPDATE_INTERVAL_MS;
    const deliver = async (channel, ctx, what, work) => {
        const address = channel.state.address;
        if (ctx.session.purpose === "eval" || address === null) {
            return;
        }
        try {
            await work(address);
        }
        catch (error) {
            deps.log(`warn could not ${what} in session ${ctx.session.id}: ${error instanceof Error ? error.message : String(error)}`);
        }
    };
    const writeLive = async (channel, address, write) => {
        const live = channel.state.live;
        let activityId;
        if (live === null) {
            activityId = (await deps.connector.send(address, markdown(write.body))).id;
        }
        else {
            activityId = live.activityId;
            await deps.connector.update(address, activityId, markdown(write.body));
        }
        channel.state.live = { activityId, text: write.text, updatedAtMs: now() };
    };
    const finish = async (channel, address, text) => {
        const [first = "", ...rest] = splitTextByJsonBytes(text, MESSAGE_TEXT_MAX_BYTES);
        const live = channel.state.live;
        if (live === null) {
            await deps.connector.send(address, markdown(first));
        }
        else {
            try {
                await deps.connector.update(address, live.activityId, markdown(first));
            }
            catch (error) {
                deps.log(`warn could not edit the Teams message ${live.activityId}, so the reply is posted as a new message: ${error instanceof Error ? error.message : String(error)}`);
                // A failed post here keeps `live`, so the turn end still removes the progress line.
                await deps.connector.send(address, markdown(first));
                try {
                    await deps.connector.delete(address, live.activityId);
                }
                catch (error) {
                    deps.log(`warn could not remove the Teams message ${live.activityId} the reply replaced: ${error instanceof Error ? error.message : String(error)}`);
                }
            }
        }
        channel.state.live = null;
        for (const part of rest) {
            await deps.connector.send(address, markdown(part));
        }
    };
    /** A progress line no reply replaced is removed; streamed text stays as the agent wrote it. */
    const settle = async (channel, address) => {
        const live = channel.state.live;
        if (live !== null && live.text === null) {
            await deps.connector.delete(address, live.activityId);
        }
        channel.state.live = null;
    };
    const typing = async (address) => {
        await deps.connector.send(address, { type: "typing" });
    };
    const handlers = {
        async "turn.started"(_event, channel, ctx) {
            channel.state.live = null;
            await deliver(channel, ctx, "show typing", typing);
        },
        async "actions.requested"(event, channel, ctx) {
            if (event.data.parentCallId !== undefined) {
                return;
            }
            await deliver(channel, ctx, "show progress", async (address) => {
                if (!stream || (channel.state.live?.text ?? null) !== null) {
                    await typing(address);
                    return;
                }
                const labels = event.data.calls.map((call) => teamsToolLabel(deps.toolLabels, call.toolName));
                await writeLive(channel, address, { body: `Running ${labels.join(", ")}…`, text: null });
            });
        },
        async "message.appended"(event, channel, ctx) {
            if (!stream || event.data.parentCallId !== undefined || event.data.text.trim() === "") {
                return;
            }
            const live = channel.state.live;
            if (live !== null && now() - live.updatedAtMs < interval) {
                return;
            }
            await deliver(channel, ctx, "stream the reply", (address) => writeLive(channel, address, {
                body: splitTextByJsonBytes(event.data.text, MESSAGE_TEXT_MAX_BYTES)[0] ?? "",
                text: event.data.text,
            }));
        },
        async "message.completed"(event, channel, ctx) {
            if (event.data.parentCallId !== undefined ||
                event.data.finishReason === "tool_call" ||
                event.data.text.trim() === "") {
                return;
            }
            await deliver(channel, ctx, "post the reply", (address) => finish(channel, address, event.data.text));
        },
        async "turn.completed"(_event, channel, ctx) {
            await deliver(channel, ctx, "clear the progress line", (address) => settle(channel, address));
        },
        async "turn.failed"(event, channel, ctx) {
            await deliver(channel, ctx, "post the failure", (address) => event.data.status === "cancelled"
                ? settle(channel, address)
                : finish(channel, address, FAILURE_TEXT));
        },
        async "session.failed"(_event, channel, ctx) {
            await deliver(channel, ctx, "post the failure", (address) => finish(channel, address, FAILURE_TEXT));
        },
    };
    if (!deps.toolApprovals) {
        return handlers;
    }
    return {
        ...handlers,
        async "action.approval_requested"(event, channel, ctx) {
            await deliver(channel, ctx, "post the approval card", async (address) => {
                const card = approvalCardActivity({
                    sessionId: ctx.session.id,
                    callId: event.data.callId,
                    toolLabel: teamsToolLabel(deps.toolLabels, event.data.toolName),
                    args: event.data.args,
                });
                const { id } = await deps.connector.send(address, card);
                channel.state.approvalCards = { ...channel.state.approvalCards, [event.data.callId]: id };
            });
        },
        async "action.approval_resolved"(event, channel, ctx) {
            const cardId = channel.state.approvalCards[event.data.callId];
            if (cardId === undefined || cardId === "") {
                return;
            }
            await deliver(channel, ctx, "update the approval card", async (address) => {
                await deps.connector.update(address, cardId, resolvedApprovalCardActivity({
                    toolLabel: teamsToolLabel(deps.toolLabels, event.data.toolName),
                    decision: event.data.decision,
                    by: event.data.by,
                    reason: event.data.reason,
                }));
            });
        },
    };
}
